CASE_ID='mab-late-constraint-eb55acdb83'; SOURCE_ID='bargaining:031'; EVENT='current_capacity_feature_counter'; THEME='late_or_out_of_order_superseded_result'; AUTHORITY={'current_counter': {'unit_price': 82.0, 'minimum_order': 40, 'washable_lining': True, 'compartments': 12}, 'supersedes': {'unit_price': 80.0, 'features': 'unspecified'}}
